package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Civics (පුරවැසි අධ්‍යාපනය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCivicsSetsPart1 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      1 -> set1[(c - 1) % set1.size]
      2 -> set2[(c - 1) % set2.size]
      3 -> set3[(c - 1) % set3.size]
      4 -> set4[(c - 1) % set4.size]
      5 -> set5[(c - 1) % set5.size]
      6 -> set6[(c - 1) % set6.size]
      7 -> set7[(c - 1) % set7.size]
      8 -> set8[(c - 1) % set8.size]
      9 -> set9[(c - 1) % set9.size]
      10 -> set10[(c - 1) % set10.size]
      else -> FlashcardBankCivicsSetsPart2.getCard(setNum, cardNum)
    }
  }

  // --- SET 1: ප්‍රජාතන්ත්‍රවාදය & මූලික ලක්ෂණ ---
  private val set1 = listOf(
    CardContentTuple("ප්‍රජාතන්ත්‍රවාදය (Democracy) යන්නෙහි වාච්‍යාර්ථය කුමක්ද?", "ග්‍රීක භාෂාවේ 'ඩෙමෝස්' (Demos = ජනතාව) සහ 'ක්‍රටෝස්' (Kratos = බලය/පාලනය) එක්වීමෙන් 'ජනතා පාලනය' යන්නයි.", "ඒබ්‍රහම් ලින්කන් දුන් අර්ථ දැක්වීම ලෝක ප්‍රසිද්ධය.", "ජනතාවගේ පාලනය (Demos + Kratos)"),
    CardContentTuple("ඒබ්‍රහම් ලින්කන් ප්‍රජාතන්ත්‍රවාදය අර්ථ දැක්වූයේ කෙසේද?", "\"ජනතාවගේ, ජනතාව විසින්, ජනතාව සඳහා පවත්වනු ලබන ආණ්ඩුව\" (Government of the people, by the people, for the people).", "ඇමරිකානු ගෙටිස්බර්ග් දේශනයේදී කළ ප්‍රකාශයකි.", "ජනතාවගේ, ජනතාව විසින්, ජනතාව සඳහා"),
    CardContentTuple("ප්‍රජාතන්ත්‍රවාදයේ ප්‍රධාන ආකෘති 2 මොනවාද?", "1. ඍජු ප්‍රජාතන්ත්‍රවාදය (Direct Democracy - පුරාණ ඇතැන්ස්හි ජනතාව ඍජුව තීරණ ගැනීම)\n2. වක්‍ර හෙවත් නියෝජිත ප්‍රජාතන්ත්‍රවාදය (Representative Democracy - තෝරාගත් නියෝජිතයින් හරහා පාලනය).", "නූතන රාජ්‍යවල නියෝජිත ක්‍රමය ක්‍රියාත්මක වේ.", "ඍජු & නියෝජිත ප්‍රජාතන්ත්‍රවාදය"),
    CardContentTuple("ප්‍රජාතන්ත්‍රවාදී පාලනයක මූලික ලක්ෂණ 4ක් මොනවාද?", "1. ජනතා පරමාධිපත්‍යය 2. නියමිත කාලවලදී පවත්වන නිදහස් හා සාධාරණ මැතිවරණ 3. නීතියේ ආධිපත්‍යය 4. මූලික මානව අයිතිවාසිකම් සුරක්ෂිත කිරීම.", "බහුතර පාලනය සහ සුළුතර අයිතිවාසිකම් රැකේ.", "ජනතා පරමාධිපත්‍යය & නිදහස් මැතිවරණ"),
